CREATE OR REPLACE FUNCTION public.social_users_unblocked(_owner uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _owner=auth.uid() OR NOT EXISTS (SELECT 1 FROM public.user_blocks b WHERE (b.blocker_id=_owner AND b.blocked_id=auth.uid()) OR (b.blocker_id=auth.uid() AND b.blocked_id=_owner)) $$;
REVOKE ALL ON FUNCTION public.social_users_unblocked(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.social_users_unblocked(uuid) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.social_audience_visible(_owner uuid,_audience text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _owner=auth.uid() OR (public.social_users_unblocked(_owner) AND CASE _audience WHEN 'public' THEN true WHEN 'followers' THEN EXISTS(SELECT 1 FROM public.follows WHERE follower_id=auth.uid() AND followee_id=_owner) WHEN 'friends' THEN EXISTS(SELECT 1 FROM public.story_close_friends WHERE owner_id=_owner AND friend_id=auth.uid()) ELSE false END) $$;
REVOKE ALL ON FUNCTION public.social_audience_visible(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.social_audience_visible(uuid,text) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.social_post_visible(_post uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.posts p WHERE p.id=_post AND (p.user_id=auth.uid() OR (p.moderation_status='approved' AND public.social_audience_visible(p.user_id,p.visibility)))) $$;
REVOKE ALL ON FUNCTION public.social_post_visible(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.social_post_visible(uuid) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.social_post_interactable(_post uuid,_comment boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.posts p WHERE p.id=_post AND p.moderation_status='approved' AND public.social_audience_visible(p.user_id,p.visibility) AND (NOT _comment OR p.allow_comments)) $$;
REVOKE ALL ON FUNCTION public.social_post_interactable(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.social_post_interactable(uuid,boolean) TO authenticated,service_role;
DROP POLICY IF EXISTS "Posts viewable by all" ON public.posts;
CREATE POLICY "Posts respect audience and moderation" ON public.posts FOR SELECT TO anon,authenticated USING(public.social_post_visible(id));
DROP POLICY IF EXISTS "Comments viewable by all" ON public.post_comments;
CREATE POLICY "Comments respect parent access" ON public.post_comments FOR SELECT TO anon,authenticated USING(public.social_post_visible(post_id));
DROP POLICY IF EXISTS "Auth users comment" ON public.post_comments;
CREATE POLICY "Authorized users comment" ON public.post_comments FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id AND public.social_post_interactable(post_id,true));
DROP POLICY IF EXISTS "Reactions viewable by all" ON public.post_reactions;
CREATE POLICY "Reactions respect parent access" ON public.post_reactions FOR SELECT TO anon,authenticated USING(public.social_post_visible(post_id));
DROP POLICY IF EXISTS "Auth users react" ON public.post_reactions;
CREATE POLICY "Authorized users react" ON public.post_reactions FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id AND public.social_post_interactable(post_id,false));
DROP POLICY IF EXISTS "Users update own reaction" ON public.post_reactions;
CREATE POLICY "Authorized users update own reaction" ON public.post_reactions FOR UPDATE TO authenticated USING(auth.uid()=user_id AND public.social_post_interactable(post_id,false)) WITH CHECK(auth.uid()=user_id AND public.social_post_interactable(post_id,false));
CREATE OR REPLACE FUNCTION public.guard_social_post_moderation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('anon','authenticated') AND ((TG_OP='INSERT' AND (NEW.moderation_status IS DISTINCT FROM 'approved' OR NEW.moderation_reason IS NOT NULL)) OR (TG_OP='UPDATE' AND (NEW.moderation_status IS DISTINCT FROM OLD.moderation_status OR NEW.moderation_reason IS DISTINCT FROM OLD.moderation_reason))) THEN RAISE EXCEPTION 'Moderation fields require authorized review'; END IF; RETURN NEW; END $$;
CREATE TRIGGER social_post_moderation_guard BEFORE INSERT OR UPDATE ON public.posts FOR EACH ROW EXECUTE FUNCTION public.guard_social_post_moderation();
CREATE OR REPLACE FUNCTION public.personal_profile_by_username(_username text) RETURNS TABLE(id uuid,username text,avatar_url text,bio text,banner_url text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.username,p.avatar_url,p.bio,p.banner_url FROM public.profiles p WHERE lower(p.username)=lower(_username) AND public.social_users_unblocked(p.id) LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.personal_profile_by_username(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.personal_profile_by_username(text) TO anon,authenticated,service_role;
COMMENT ON FUNCTION public.personal_profile_by_username(text) IS 'Caller-bound safe social identity projection; no account or verification fields.';
CREATE POLICY "Vault per-card privacy restriction" ON public.vault_cards AS RESTRICTIVE FOR SELECT TO anon,authenticated USING(user_id=auth.uid() OR public.social_audience_visible(user_id,visibility));